import {BellIcon} from '@primer/octicons-react'
import {Blankslate} from '@primer/react/experimental'

import {BudgetRequestsSection} from './components/BudgetRequestsSection'
import {RequestCardRow} from './components/RequestCardRow'
import {RequestRowList} from './components/RequestRow'
import {SectionHeading} from './components/SectionHeading'
import {UpgradeBanner} from './components/UpgradeBanner'
import type {MemberRequestsPayload} from './types'

/**
 * "Requests from members" page, shared between the organization settings
 * scope (feature requests + add-on requests with action CTAs) and the
 * enterprise settings scope (aggregated add-on requests + per-organization
 * Copilot budget requests).
 */
export function MemberRequests({
  scope,
  entity,
  featureRequests,
  addonRequests,
  budgetRequests,
  watch,
}: MemberRequestsPayload) {
  const isEnterprise = scope === 'enterprise'
  const hasFeatureRequests = (featureRequests?.items.length ?? 0) > 0
  const hasAddonRequests = addonRequests.length > 0
  const hasBudgetRequests = (budgetRequests?.organizations.length ?? 0) > 0

  return (
    <div data-testid="member-requests">
      {isEnterprise && (
        <p className="color-fg-muted">
          Members of your organizations can request features and additional Copilot budget that are billed to{' '}
          {entity.name}. Review their requests to discover what your teams need.
        </p>
      )}

      {isEnterprise && !hasAddonRequests && !hasBudgetRequests && (
        <div data-testid="member-requests-empty">
          <Blankslate border>
            <Blankslate.Visual>
              <BellIcon size="medium" />
            </Blankslate.Visual>
            <Blankslate.Heading as="h2">No pending requests</Blankslate.Heading>
            <Blankslate.Description>
              When members of your organizations request enterprise-billed features or additional Copilot budget, they
              will show up here.
            </Blankslate.Description>
          </Blankslate>
        </div>
      )}

      {featureRequests && hasFeatureRequests && (
        <section aria-label={`Member requests for GitHub ${featureRequests.upgrade.targetPlanLabel}`}>
          <SectionHeading
            id="features"
            title={`Member requests for GitHub ${featureRequests.upgrade.targetPlanLabel}`}
            watch={watch}
          />
          <p className="color-fg-muted">
            Discover your organization’s specific needs and uncover your users’ ideal workflows to enhance productivity
            and collaboration.
          </p>
          <RequestRowList label={`Member requests for GitHub ${featureRequests.upgrade.targetPlanLabel}`}>
            <UpgradeBanner upgrade={featureRequests.upgrade} entity={entity} />
            {featureRequests.items.map(item => (
              <RequestCardRow key={item.key} card={item} />
            ))}
          </RequestRowList>
        </section>
      )}

      {hasAddonRequests && (
        <section aria-label="Member requests for GitHub Add-Ons">
          <SectionHeading
            id="addons"
            title="Member requests for GitHub Add-Ons"
            watch={hasFeatureRequests ? null : watch}
          />
          <RequestRowList label="Member requests for GitHub Add-Ons">
            {addonRequests.map(addon => (
              <RequestCardRow key={addon.key} card={addon} />
            ))}
          </RequestRowList>
        </section>
      )}

      {budgetRequests && hasBudgetRequests && <BudgetRequestsSection budgetRequests={budgetRequests} />}
    </div>
  )
}
