/**
 * Shared payload shape served by the monolith for both member request pages:
 *
 * - Organization: Orgs::Settings::MemberFeatureRequestsController#show
 *   (InProductTargeting::MemberRequests::OrganizationPagePayload)
 * - Enterprise: Businesses::MemberRequestsController#show
 *   (InProductTargeting::MemberRequests::EnterprisePagePayload)
 */
export interface MemberRequestsPayload {
  scope: 'organization' | 'enterprise'
  entity: EntityInfo
  /** Organization scope only: plan feature requests plus the upgrade banner. */
  featureRequests: FeatureRequestsSection | null
  addonRequests: AddonRequest[]
  /** Enterprise scope only: additional Copilot budget requests per organization. */
  budgetRequests: BudgetRequestsSection | null
  /** Organization scope only: notification subscription state for the page. */
  watch: WatchSettings | null
}

export interface EntityInfo {
  login: string
  name: string
  avatarUrl: string
}

export interface AnalyticsEvent {
  category: string
  action: string
  label: string
}

export interface Requester {
  login: string
  avatarUrl: string
}

export interface RequestCard {
  key: string
  name: string
  description: string
  docsUrl: string
  icon: string
  count: number
  docsAnalytics: AnalyticsEvent
}

export interface FeatureRequestsSection {
  upgrade: UpgradeBannerInfo
  items: RequestCard[]
}

export interface UpgradeBannerInfo {
  currentPlanName: string
  targetPlanLabel: string
  ctaKind: 'trial' | 'upgrade'
  ctaText: string
  ctaUrl: string
  ctaAnalytics: AnalyticsEvent
  customerStoryUrl: string
  customerStoryAnalytics: AnalyticsEvent
}

export interface AddonRequest extends RequestCard {
  showNewBadge: boolean
  /** Enterprise scope: recent requesters across member organizations. */
  requesters: Requester[] | null
  /** Enterprise scope: "Requested in org-a, org-b, and org-c". */
  requestedInText: string | null
  /** Organization scope: CTAs for acting on the add-on request. */
  actions: AddonActions | null
}

export interface AddonActions {
  enterpriseRequest: EnterpriseRequestAction | null
  primaryCta: PrimaryCta | null
  secondaryCta: SecondaryCta | null
}

export interface EnterpriseRequestAction {
  featureKey: string
  featureName: string
  state: 'none' | 'requested' | 'dismissed'
  dismissedAt: string | null
  requestPath: string
  contactAdminUrl: string
  analytics: AnalyticsEvent
}

export interface PrimaryCta {
  text: string
  url: string
  analytics: AnalyticsEvent
  /** When present the CTA submits these fields to `url` instead of navigating. */
  form: {method: string; fields: Record<string, string>} | null
}

export interface SecondaryCta {
  text: string
  url: string
  analytics: AnalyticsEvent
}

export interface BudgetRequestsSection {
  grandTotal: string
  organizationCount: number
  organizations: BudgetOrganizationRow[]
}

export interface BudgetOrganizationRow {
  login: string
  avatarUrl: string
  total: string
  requesterCount: number
  requesters: Requester[]
}

export interface WatchSettings {
  subscriptionPath: string
  subscriptionType: 'watching' | 'ignoring' | 'custom'
  subscribableFeatures: Array<{key: string; name: string}>
  subscribedFeatures: string[]
}

export function analyticsAttribute(event: AnalyticsEvent | null | undefined): string | undefined {
  return event ? JSON.stringify(event) : undefined
}

export function pluralize(count: number, singular: string): string {
  return count === 1 ? singular : `${singular}s`
}
