import {GitHubAvatar} from '@github-ui/github-avatar'

import {type BudgetRequestsSection as BudgetRequestsData, pluralize} from '../types'
import {RequesterAvatars} from './RequesterAvatars'
import {RequestRow, RequestRowList} from './RequestRow'
import {SectionHeading} from './SectionHeading'

/**
 * Per-organization breakdown of additional Copilot budget requests with the
 * enterprise-wide grand total (enterprise scope).
 */
export function BudgetRequestsSection({budgetRequests}: {budgetRequests: BudgetRequestsData}) {
  return (
    <section aria-label="Member requests for Additional Copilot Budget">
      <SectionHeading
        id="budget-requests"
        title="Member requests for Additional Copilot Budget"
        description={
          <span data-testid="budget-requests-grand-total">
            {budgetRequests.grandTotal} requested across {budgetRequests.organizationCount}{' '}
            {pluralize(budgetRequests.organizationCount, 'organization')}
          </span>
        }
      />
      <RequestRowList label="Budget requests by organization">
        {budgetRequests.organizations.map(organization => (
          <RequestRow
            key={organization.login}
            id={`budget-${organization.login}`}
            leadingVisual={<GitHubAvatar src={organization.avatarUrl} alt={organization.login} size={40} square />}
            title={<span className="h4">{organization.login}</span>}
            figure={organization.total}
            figureLabel="requested"
          >
            <RequesterAvatars requesters={organization.requesters}>
              {organization.requesterCount} {pluralize(organization.requesterCount, 'member')} requested additional
              budget
            </RequesterAvatars>
          </RequestRow>
        ))}
      </RequestRowList>
    </section>
  )
}
