import {BellSlashIcon, EyeIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Checkbox, FormControl} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useState} from 'react'

import {updateSubscription} from '../api'
import type {WatchSettings} from '../types'

/**
 * Notification subscription menu for the organization page. React port of
 * Organizations::MemberRequests::WatchButtonComponent: choose between
 * watching all member request activity, ignoring it, or a custom selection
 * of features.
 */
export function WatchButton({watch}: {watch: WatchSettings}) {
  const [subscriptionType, setSubscriptionType] = useState(watch.subscriptionType)
  const [subscribedFeatures, setSubscribedFeatures] = useState(watch.subscribedFeatures)
  const [customDialogOpen, setCustomDialogOpen] = useState(false)
  const [pendingFeatures, setPendingFeatures] = useState<string[]>([])
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const notificationsEnabled = subscriptionType === 'watching' || subscriptionType === 'custom'

  async function selectWatching() {
    setError(null)
    try {
      await updateSubscription(watch.subscriptionPath, {type: 'watching'})
      setSubscriptionType('watching')
      setSubscribedFeatures(watch.subscribableFeatures.map(feature => feature.key))
    } catch {
      // Keep the previous selection so the user can retry.
      setError('Something went wrong updating your notification settings. Please try again.')
    }
  }

  async function selectIgnoring() {
    setError(null)
    try {
      await updateSubscription(watch.subscriptionPath, {type: 'ignoring'})
      setSubscriptionType('ignoring')
      setSubscribedFeatures([])
    } catch {
      // Keep the previous selection so the user can retry.
      setError('Something went wrong updating your notification settings. Please try again.')
    }
  }

  function openCustomDialog() {
    setPendingFeatures(subscriptionType === 'custom' ? subscribedFeatures : [])
    setError(null)
    setCustomDialogOpen(true)
  }

  async function applyCustom() {
    setSaving(true)
    setError(null)
    try {
      await updateSubscription(watch.subscriptionPath, {type: 'custom', features: pendingFeatures})
      setSubscribedFeatures(pendingFeatures)
      // An empty custom selection is stored as "never notify", matching the
      // server-side subscription_type derivation.
      setSubscriptionType(pendingFeatures.length === 0 ? 'ignoring' : 'custom')
      setCustomDialogOpen(false)
    } catch {
      // Leave the dialog open so the user can retry.
      setError('Something went wrong updating your notification settings. Please try again.')
    } finally {
      setSaving(false)
    }
  }

  function togglePendingFeature(key: string) {
    setPendingFeatures(current => (current.includes(key) ? current.filter(value => value !== key) : [...current, key]))
  }

  return (
    <>
      <ActionMenu>
        <ActionMenu.Button
          leadingVisual={notificationsEnabled ? EyeIcon : BellSlashIcon}
          data-testid="member-requests-watch-button"
        >
          {notificationsEnabled ? 'Unwatch' : 'Stop ignoring'}
        </ActionMenu.Button>
        <ActionMenu.Overlay width="medium">
          <ActionList selectionVariant="single" aria-label="Notification settings">
            {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
            <ActionList.Item selected={subscriptionType === 'watching'} onSelect={() => void selectWatching()}>
              All Activity
              <ActionList.Description variant="block">
                Notified of all notifications on this page.
              </ActionList.Description>
            </ActionList.Item>
            <ActionList.Item selected={subscriptionType === 'ignoring'} onSelect={() => void selectIgnoring()}>
              Ignore
              <ActionList.Description variant="block">Never be notified.</ActionList.Description>
            </ActionList.Item>
            <ActionList.Item selected={subscriptionType === 'custom'} onSelect={openCustomDialog}>
              Custom
              <ActionList.Description variant="block">Select events you want to be notified of.</ActionList.Description>
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
      {error && !customDialogOpen && (
        <span role="alert" className="color-fg-danger f6 ml-2">
          {error}
        </span>
      )}
      {customDialogOpen && (
        <Dialog
          title="Custom"
          subtitle="Select events you want to be notified of."
          onClose={() => setCustomDialogOpen(false)}
          footerButtons={[
            {content: 'Cancel', onClick: () => setCustomDialogOpen(false)},
            {content: 'Apply', buttonType: 'primary', onClick: () => void applyCustom(), disabled: saving},
          ]}
        >
          {error && (
            <p role="alert" className="color-fg-danger f6">
              {error}
            </p>
          )}
          {watch.subscribableFeatures.map(feature => (
            <FormControl key={feature.key}>
              <Checkbox
                checked={pendingFeatures.includes(feature.key)}
                onChange={() => togglePendingFeature(feature.key)}
                value={feature.key}
              />
              <FormControl.Label>{feature.name}</FormControl.Label>
            </FormControl>
          ))}
        </Dialog>
      )}
    </>
  )
}
