export interface RequestRowProps {
  id: string
  /** Leading visual: feature icon in a circle, or an organization avatar. */
  leadingVisual: React.ReactNode
  title: React.ReactNode
  description?: React.ReactNode
  /** Trailing figure, e.g. the request count or a formatted budget total. */
  figure: React.ReactNode
  figureLabel: string
  children?: React.ReactNode
}

/**
 * Shared list-row layout used by feature request, add-on request and budget
 * request rows on both the organization and enterprise pages.
 */
export function RequestRow({id, leadingVisual, title, description, figure, figureLabel, children}: RequestRowProps) {
  return (
    <li className="Box-row" data-testid={`member-request-row-${id}`}>
      <div className="d-flex flex-column flex-md-row">
        <div className="d-flex flex-items-start mr-2 mb-2 mb-md-0">{leadingVisual}</div>
        <div className="d-flex flex-column col-12 col-md-8 min-width-0">
          <div className="d-flex flex-row flex-items-center flex-wrap">{title}</div>
          {description}
          {children}
        </div>
        <div className="d-flex flex-md-justify-end flex-items-baseline col-md-4 mt-2 mt-md-0">
          <span className="h3 mr-2" data-testid={`member-request-figure-${id}`}>
            {figure}
          </span>
          <span className="color-fg-muted" data-testid={`member-request-figure-label-${id}`}>
            {figureLabel}
          </span>
        </div>
      </div>
    </li>
  )
}

export function RequestRowList({label, children}: {label: string; children: React.ReactNode}) {
  return (
    <ul className="Box list-style-none mt-3 mb-3" aria-label={label}>
      {children}
    </ul>
  )
}
